-- Модуль 11: остатки и резервы переехали в сервис «Склад» (своя база
-- MySQL). У «Заказов» остаются каталог с ценами, заказы и outbox.
DROP TABLE stock;

-- Номер заказа выдаётся из последовательности ДО записи заказа: он нужен
-- «Складу» как ключ идемпотентности резерва (NextOrderID). Поэтому id
-- вставляется явно — GENERATED BY DEFAULT вместо ALWAYS.
ALTER TABLE orders ALTER COLUMN id SET GENERATED BY DEFAULT;

-- Outbox теперь публикуется в Kafka: значение — protobuf (events.v1),
-- у события глобальный id для дедупликации у потребителей и контекст
-- трассы запроса. Таблица модуля 10 (JSON) пересоздаётся: публикатора у
-- неё не было, её события никто не ждёт. В продакшне так нельзя — сначала
-- дожидаются публикации старых событий, потом меняют формат.
DROP TABLE outbox;
CREATE TABLE outbox (
    id            bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    event_id      text        NOT NULL UNIQUE,
    event_type    text        NOT NULL,
    aggregate_id  bigint      NOT NULL,
    payload       bytea       NOT NULL,
    trace_context jsonb       NOT NULL DEFAULT '{}',
    created_at    timestamptz NOT NULL,
    published_at  timestamptz
);
CREATE INDEX outbox_pending_idx ON outbox (id) WHERE published_at IS NULL;

-- История заказов покупателя страницами: WHERE customer_id = ? AND id < ?
-- ORDER BY id DESC — по этому индексу без сортировки.
CREATE INDEX orders_customer_id_id_idx ON orders (customer_id, id DESC);
DROP INDEX orders_customer_id_idx;

